The fix:

```c
static bool coap_response_matches(const struct coap_packet *response, uint16_t id, uint8_t tkl,
				  uint8_t *token)
{
	bool ret = false;
	uint8_t response_type = coap_header_get_type(response);
	uint8_t response_token[COAP_TOKEN_MAX_LEN];
	uint16_t response_id = coap_header_get_id(response);
	uint8_t response_tokenlen = coap_header_get_token(response, response_token);
	bool response_is_empty = is_empty_message(response);

	switch (response_type) {
	case COAP_TYPE_ACK:
		if (response_is_empty && response_id == id) {
			// empty ACK must match id and has no token
			ret = true;
		} else if ((response_tokenlen == tkl) && (response_id == id) &&
			   ((tkl == 0U) || (memcmp(&response_token[0], token, tkl) == 0))) {
			// Piggybacked must match id and token (if there is a token)
			ret = true;
		}
		break;
	case COAP_TYPE_CON:
		__fallthrough;
	case COAP_TYPE_NON_CON:
		/* Separate response must match token, if there is no token fall back on comparing
		 * id */
		if (response_tokenlen != tkl) {
			ret = false;
		} else if ((tkl != 0U) && (memcmp(&response_token[0], token, tkl) == 0)) {
			ret = true;
		} else if ((tkl == 0U) && (response_id == id)) {
			ret = true;
		}
		break;

	case COAP_TYPE_RESET:
		/* Reset must match id */
		if (response_id == id) {
			ret = true;
		}
		break;
	default:
		ret = false;
		break;
	}

	return ret;
}

struct coap_reply *coap_response_received(
	const struct coap_packet *response,
	const struct sockaddr *from,
	struct coap_reply *replies, size_t len)
{
	struct coap_reply *r;
	uint8_t token[COAP_TOKEN_MAX_LEN];
	uint16_t id;
	uint8_t tkl;
	size_t i;

	if (!is_empty_message(response) && coap_packet_is_request(response)) {
		/* Request can't be response */
		return NULL;
	}

	id = coap_header_get_id(response);
	tkl = coap_header_get_token(response, token);

	for (i = 0, r = replies; i < len; i++, r++) {
		int age;

		if (r->reply == NULL) {
			/* reply not used */
			continue;
		}

		if (coap_response_matches(response, r->id, r->tkl, &r->token[0]) == false) {
			continue;
		}

		age = coap_get_option_int(response, COAP_OPTION_OBSERVE);
		/* handle observed requests only if received in order */
		if (age == -ENOENT || coap_age_is_newer(r->age, age)) {
			r->age = age;
			if (coap_header_get_code(response) != COAP_RESPONSE_CODE_CONTINUE) {
				r->reply(response, r, from);
			}
		}

		return r;
	}

	return NULL;
}
